//
// Stand-in for OpenTitan's abstract primitive `prim_xor2` (normally generated by primgen).
// Selects the generic implementation prim_generic_xor2.
module prim_xor2 #(
  parameter int Width = 1
) (
  input        [Width-1:0] in0_i,
  input        [Width-1:0] in1_i,
  output logic [Width-1:0] out_o
);

  prim_generic_xor2 #(
    .Width (Width)
  ) u_impl (
    .in0_i (in0_i),
    .in1_i (in1_i),
    .out_o (out_o)
  );

endmodule
